[InitializeOnLoad] public static class NotebookBuilder {
const string Root="Assets/Project/Dev/Sandbox/Interface/PlayerUI/Notebook";const string UIRoot="Assets/Project/UI/Notebook";
static Font regular,bold;static readonly Dictionary<string,Sprite> sprites=new Dictionary<string,Sprite>();
static NotebookBuilder(){EditorApplication.update+=()=>{if(!File.Exists("Library/NotebookBuild.request")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying)return;File.Delete("Library/NotebookBuild.request");try{Build();File.WriteAllText("Library/NotebookBuild.result","PASS");}catch(Exception e){File.WriteAllText("Library/NotebookBuild.result",e.ToString());Debug.LogException(e);}};}
static RectTransform Rect(string name,Transform parent,float x,float y,float w,float h){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
static Image Image(string name,Transform parent,string sprite,float x,float y,float w,float h,bool sliced=false){var r=Rect(name,parent,x,y,w,h);var i=r.gameObject.AddComponent<Image>();if(sprite!=null)i.sprite=sprites[sprite];i.raycastTarget=false;if(sliced){i.type=UnityEngine.UI.Image.Type.Sliced;i.pixelsPerUnitMultiplier=sprite=="FR_PencilCell"?8:3;}return i;}
static Text Text(string name,Transform parent,string value,float x,float y,float w,float h,int size,bool heavy=false,TextAnchor align=TextAnchor.MiddleLeft){var r=Rect(name,parent,x,y,w,h);var t=r.gameObject.AddComponent<Text>();t.font=heavy?bold:regular;t.text=value;t.fontSize=size;t.alignment=align;t.color=new Color(.05f,.17f,.17f);t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Truncate;t.raycastTarget=false;return t;}
static void ImportSprites(){sprites.Clear();var report=new StringBuilder();foreach(var path in Directory.GetFiles(UIRoot+"/Sprites","*.png").OrderBy(p=>p)){
AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.alphaIsTransparency=true;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.maxTextureSize=4096;importer.filterMode=FilterMode.Bilinear;importer.SaveAndReimport();
var raw=new Texture2D(2,2,TextureFormat.RGBA32,false);raw.LoadImage(File.ReadAllBytes(path));var pixels=raw.GetPixels32();int w=raw.width,h=raw.height,minX=w,minY=h,maxX=0,maxY=0,transparent=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){byte a=pixels[y*w+x].a;if(a<16)transparent++;if(a>24){minX=Math.Min(minX,x);minY=Math.Min(minY,y);maxX=Math.Max(maxX,x);maxY=Math.Max(maxY,y);}}
if(transparent==0)throw new Exception("Missing actual alpha: "+path);string id=Path.GetFileNameWithoutExtension(path);if(id=="FR_PencilCell"&&pixels[h/2*w+w/2].a>16)throw new Exception("Cell interior must be transparent");var rect=new UnityEngine.Rect(Math.Max(0,minX-2),Math.Max(0,minY-2),Math.Min(w,maxX+3)-Math.Max(0,minX-2),Math.Min(h,maxY+3)-Math.Max(0,minY-2));var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);float border=id=="FR_PencilCell"?32:id.StartsWith("BG_")?64:0;var sprite=Sprite.Create(texture,rect,new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(border,border,border,border));sprite.name=id;string asset=UIRoot+"/Sprites/"+id+".sprite.asset";var old=AssetDatabase.LoadAssetAtPath<Sprite>(asset);if(old){EditorUtility.CopySerialized(sprite,old);UnityEngine.Object.DestroyImmediate(sprite);sprite=old;}else AssetDatabase.CreateAsset(sprite,asset);sprites[id]=sprite;report.AppendLine($"{id}: {w}x{h}; alpha exterior {(100f*transparent/pixels.Length):F1}%; sprite rect {rect.width}x{rect.height}");UnityEngine.Object.DestroyImmediate(raw);
}if(sprites.Count!=12)throw new Exception("Expected 12 sprites, got "+sprites.Count);File.WriteAllText(Root+"/SpriteVerification.txt",report.ToString()+"PASS: 12 original image_gen PNGs, native trimmed Sprite assets, actual alpha, empty cell center, no baked text.\n");}
public static void Build(){ImportSprites();regular=AssetDatabase.LoadAssetAtPath<Font>("Assets/Font/public/static/alternative/Pretendard-Regular.ttf");bold=AssetDatabase.LoadAssetAtPath<Font>("Assets/Font/public/static/alternative/Pretendard-Bold.ttf");string path="Assets/Project/Dev/Sandbox/Interface/PlayerUI/SC_PlayerUI.unity";var scene=SceneManager.GetSceneByPath(path);bool close=!scene.isLoaded;if(close)scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);try{
var c=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PlayerUIController>(true)).Single();var previous=c.hud.transform.Find("Information Notebook - Editable");if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);
var overlay=Rect("Information Notebook - Editable",c.hud.transform,0,0,0,0);overlay.anchorMin=Vector2.zero;overlay.anchorMax=Vector2.one;overlay.pivot=new Vector2(.5f,.5f);overlay.offsetMin=overlay.offsetMax=Vector2.zero;var dim=Image("Backdrop Dim - Opacity Editable",overlay,null,0,0,1920,1080);dim.color=new Color(0,0,0,.18f);var dr=dim.rectTransform;dr.anchorMin=Vector2.zero;dr.anchorMax=Vector2.one;dr.offsetMin=dr.offsetMax=Vector2.zero;
var panel=Rect("Notebook Panel",overlay,0,0,980,900);panel.anchorMin=panel.anchorMax=panel.pivot=new Vector2(.5f,.5f);panel.anchoredPosition=new Vector2(70,-10);
Image("Leather Cover - 9 Slice",panel,"BG_NotebookLeather",0,0,980,900,true);Image("Ivory Paper - 9 Slice",panel,"BG_NotebookPaper",48,24,908,850,true);
for(int i=0;i<6;i++){var ring=Image("Brass Binding "+i,panel,"DEC_BrassRing",15,105+i*132,54,35);ring.preserveAspect=true;}
Text("Title",panel,"내 정보 수첩",106,61,575,60,44,true);Text("Subtitle",panel,"구매한 정보만 기록됩니다",108,126,650,34,23);var page=Text("Page Range",panel,"1–8 / 17R",714,77,181,36,23,false,TextAnchor.MiddleRight);
var underline=Image("Pencil Title Underline",panel,"FR_PencilCell",108,174,786,5);underline.color=new Color(1,1,1,.6f);
Text("Round Header",panel,"ROUND",110,202,108,52,22,true,TextAnchor.MiddleCenter);
string[] ids={"Straw","Timber","Brick"};var colors=new[]{new Color(.43f,.24f,.035f),new Color(.13f,.29f,.12f),new Color(.46f,.07f,.045f)};
for(int i=0;i<3;i++){var icon=Image(ids[i]+" Pencil Icon",panel,"IC_"+ids[i]+"Pencil",238+i*222,199,55,55);icon.preserveAspect=true;Text(ids[i]+" Header",panel,ids[i],302+i*222,202,137,52,28,true).color=colors[i];}
var view=overlay.gameObject.AddComponent<InformationNotebookView>();view.overlay=overlay.gameObject;view.pageRange=page;view.roundNumbers=new Text[8];view.roundStates=new Text[8];view.cellValues=new Text[24];view.cellMarks=new Image[24];view.currentBands=new Image[8];view.currentMarkers=new Image[8];view.cellFrames=new Image[32];view.riseMark=sprites["MK_RiseRed"];view.fallMark=sprites["MK_FallBlue"];view.flatMark=sprites["MK_FlatGraphite"];
for(int row=0;row<8;row++){var group=Rect("Visible Row "+(row+1),panel,0,264+row*64,910,64);view.currentBands[row]=Image("Current Row - Pencil Highlight",group,"MK_CurrentRow",108,0,786,62);view.currentBands[row].color=new Color(1,1,1,.65f);view.currentBands[row].enabled=false;view.currentMarkers[row]=Image("Current Bookmark",group,"IC_CurrentBookmark",78,12,25,42);view.currentMarkers[row].enabled=false;view.cellFrames[row*4]=Image("Round Pencil Frame",group,"FR_PencilCell",110,0,108,62,true);view.roundNumbers[row]=Text("Round Number",group,(row+1)+"R",114,3,100,36,29,true,TextAnchor.MiddleCenter);view.roundStates[row]=Text("Round State",group,"",114,39,100,19,15,false,TextAnchor.MiddleCenter);
for(int col=0;col<3;col++){int i=row*3+col;var cell=Rect(ids[col]+" Slot",group,224+col*222,0,220,62);view.cellFrames[row*4+col+1]=Image("Pencil Frame",cell,"FR_PencilCell",0,0,220,62,true);view.cellMarks[i]=Image("Owned Information Mark",cell,"MK_RiseRed",18,11,184,40);view.cellMarks[i].enabled=false;view.cellValues[i]=Text("Direction - Editable Text",cell,"",12,9,196,44,27,true,TextAnchor.MiddleCenter);}}
var track=Image("Pencil Scroll Track",panel,"FR_PencilCell",918,246,512,4);track.rectTransform.localRotation=Quaternion.Euler(0,0,-90);track.color=new Color(1,1,1,.45f);var thumb=Image("Brass Scroll Thumb",panel,"BG_NotebookLeather",912,246,12,64,true);thumb.color=new Color(.85f,.75f,.5f);view.scrollThumb=thumb.rectTransform;
Text("Empty Slot Legend",panel,"빈칸 = 미보유 정보",110,822,380,40,21);Text("Keyboard Guide",panel,"W / S 스크롤 · Q / Tab 닫기",505,822,388,40,21,false,TextAnchor.MiddleRight);
c.notebook=view;overlay.gameObject.SetActive(false);PrefabUtility.SaveAsPrefabAsset(overlay.gameObject,UIRoot+"/PF_InformationNotebook.prefab");PrefabUtility.SaveAsPrefabAsset(c.hud,"Assets/Project/Dev/Sandbox/Interface/PlayerUI/Prefabs/PF_PlayerHUD.prefab");PrefabUtility.SaveAsPrefabAsset(c.gameObject,"Assets/Project/Dev/Sandbox/Interface/PlayerUI/Prefabs/PF_PlayerUIRig.prefab");EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();CheckAndCapture(c,view);
}finally{if(close)EditorSceneManager.CloseScene(scene,true);AssetDatabase.Refresh();}}
static void CheckAndCapture(PlayerUIController c,InformationNotebookView v){c.Awake();var data=new[]{new Info(2,Company.Straw,Direction.Rise,Company.Timber,Direction.Fall),new Info(3,Company.Timber,Direction.Rise,Company.Brick,Direction.Rise),new Info(4,Company.Straw,Direction.Rise,Company.Timber,Direction.Rise),new Info(5,Company.Timber,Direction.Rise,Company.Brick,Direction.Rise)};v.Present(4,17,data);v.SetOpen(true,4);if(v.FirstRound!=2||v.cellValues[0].text!="↑ 상승"||v.cellValues[1].text!="↓ 하락"||v.cellMarks[2].enabled)throw new Exception("Notebook known/unknown mapping");v.Scroll(100);if(v.FirstRound!=10)throw new Exception("End scroll clamp");v.Scroll(-100);if(v.FirstRound!=1)throw new Exception("Start scroll clamp");v.Scroll(1);Capture(c);v.SetOpen(false,4);if(!c.movement.enabled||!c.detection.enabled)throw new Exception("Notebook close restore");File.WriteAllText(Root+"/Verification.txt","PASS: 12 sprites, editable native Text/Image, 8 visible rows / 17 rounds, owned info only, unknown cells blank, current/past status, scroll limits, movement lock/restore, scene and 3 prefabs saved. Notebook preview uses labeled editor sample data; runtime uses actual owned Info records.");}
static void Capture(PlayerUIController c){var canvas=c.hud.GetComponent<Canvas>();var mode=canvas.renderMode;var camera=canvas.worldCamera;float distance=canvas.planeDistance;var target=c.view.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1920,1080,24);var tex=new Texture2D(1920,1080,TextureFormat.RGB24,false);var round=c.hud.transform.Find("Round Timer - Top Right/Round").GetComponent<Text>();var oldRound=round.text;try{round.text="4 / 17 ROUND";canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=c.view;canvas.planeDistance=1;c.view.targetTexture=rt;Canvas.ForceUpdateCanvases();c.view.Render();RenderTexture.active=rt;tex.ReadPixels(new UnityEngine.Rect(0,0,1920,1080),0,0);tex.Apply();File.WriteAllBytes(Root+"/Preview/NotebookAssembled.png",tex.EncodeToPNG());}finally{round.text=oldRound;c.view.targetTexture=target;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=camera;canvas.planeDistance=distance;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}}
}
